<?php
require __DIR__ . '/includes/db.php';
require __DIR__ . '/includes/helpers.php';
$productos = $pdo->query('SELECT id, nombre, descripcion, precio, categoria FROM productos WHERE activo = 1 ORDER BY id ASC')->fetchAll();
$success = false; $error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    $nombre = trim((string)($_POST['nombre'] ?? ''));
    $correo = trim((string)($_POST['correo'] ?? ''));
    $mensaje = trim((string)($_POST['mensaje'] ?? ''));
    if (mb_strlen($nombre) < 2 || mb_strlen($nombre) > 100 || !filter_var($correo, FILTER_VALIDATE_EMAIL) || mb_strlen($mensaje) < 10 || mb_strlen($mensaje) > 3000) {
        $error = 'Revisa el nombre, correo y mensaje (mínimo 10 caracteres).';
    } else {
        $stmt = $pdo->prepare('INSERT INTO mensajes (nombre, correo, mensaje) VALUES (?, ?, ?)');
        $stmt->execute([$nombre, $correo, $mensaje]);
        $success = true;
    }
}
$iconos = ['Bebidas' => '☕', 'Postres' => '🍰', 'Comidas' => '🥪'];
